function studentsWithoutSnack(students: number[], snacks: number[]): number {
  const queue = [...students];
  let top = 0, misses = 0;
  while (queue.length && misses < queue.length) {
    const s = queue.shift()!;
    if (s === snacks[top]) { top++; misses = 0; }
    else { queue.push(s); misses++; }
  }
  return queue.length;
}

