class Solution:
    def studentsWithoutSnack(self, students: List[int], snacks: List[int]) -> int:
        q = deque(students)
        top = misses = 0
        while q and misses < len(q):
            s = q.popleft()
            if s == snacks[top]:
                top += 1
                misses = 0
            else:
                q.append(s)
                misses += 1
        return len(q)

