function studentsWithoutSnack(students: number[], snacks: number[]): number {
  const want = [0, 0];
  for (const s of students) want[s]++;
  for (const k of snacks) {
    if (want[k] === 0) break;
    want[k]--;
  }
  return want[0] + want[1];
}

